def-hyp[predicate](
    list-partial(Type.annotation(@X, Set(P@Set.def.order.partial)), Type.annotation(@a, P@Set.def.order.partial)),
    Eq(a, Set.order.min(X, P@Set.def.order.partial)),
    Logic.and(
        Set.mem(a, X),
        Logic.forall-typed(@x, X, Logic.neg(Rl.apply($\lt$@Set.def.order.partial, x, a)))
    )
)
